rd,#fff);color:var(--ink)}.field input:focus,.field select:focus{outline:2px solid var(--accent);outline-offset:2px}.check-row{display:flex;align-items:center;gap:13px;padding:17px 0;border-bottom:1px solid var(--line);cursor:pointer}.check-row:last-child{border-bottom:0}.check-row input{appearance:none;min-width:22px;height:22px;margin:0;border:1.5px solid #a1abb3;border-radius:6px;background:var(--card,#fff);display:grid;place-items:center;cursor:pointer}.check-row input:checked{background:var(--accent);border-color:var(--accent)}.check-row input:checked:after{content:'✓';color:var(--on-accent,#fff);font-size:15px;font-weight:750}.check-row strong{font-size:13px;font-weight:600}.check-row input:checked+span strong{text-decoration:line-through;color:var(--muted)}.check-row .subtle{display:block}.footer{max-width:1260px;margin:34px auto 0;padding:25px 5%;border-top:1px solid var(--line,#e3e7eb);font-size:11px;color:var(--muted,#6b7482);display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.source-list{padding:18px 0;font-size:12px;line-height:2}.source-list a{display:block}.source-box{margin-top:28px;font-size:12px}.source-box summary{cursor:pointer;min-height:44px;display:flex;align-items:center;gap:10px}.source-box p{max-width:800px}.notice{border-radius:10px;padding:14px 17px;background:var(--soft);font-size:12px;color:var(--ink)}.notice .icon{width:17px;height:17px}.empty{text-align:center;padding:45px 15px;color:var(--muted)}.sr-only{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}.skip{position:fixed;top:-70px;left:20px;z-index:100;background:var(--card,#fff);padding:10px}.skip:focus{top:10px}*:focus-visible{outline:3px solid var(--accent,#b74735);outline-offset:4px}dialog{color:var(--ink);background:var(--card,#fff);border:1px solid var(--line);border-radius:18px;width:min(500px,92vw);padding:28px}dialog::backdrop{background:#101b2d88;backdrop-filter:blur(3px)}dialog form{display:grid;gap:16px}dialog h2{font-size:24px}.t