RUNTIME = r'''
const icons=__ICONS__;
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.shield}</svg>`;
function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v===null?fallback:v;}catch{return fallback;}}
let lang=read('prepared-language','da');if(!['da','en'].includes(lang))lang='da';
const t=(da,en)=>lang==='da'?da:en;
const esc=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{storageOK=false;toast(t('Browseren kunne ikke gemme. Behold siden åben.','Your browser could not save. Keep this page open.'));}}
function languageButtons(){return `<div class="langs" aria-label="${t('Vælg sprog','Choose language')}"><button data-lang="da" aria-pressed="${lang==='da'}">DA</button><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div>`;}
function header(name,mark,links=''){return `<a class="skip" href="#main">${t('Gå til indhold','Skip to content')}</a><header class="topbar"><a class="brand" href="index.html"><span class="brand-mark">${icon(mark)}</span>${name}</a><nav class="toplinks" aria-label="${t('Navigation','Navigation')}">${links}<span class="badge">${t('Koncept 2026','Concept 2026')}</span>${languageButtons()}</nav></header>`;}
function footer(){return `<footer class="footer"><span>${t('Uafhængig konceptprototype til dansk borgerberedskab · Ikke en officiel myndighedstjeneste.','Independent concept for preparedness in Denmark · Not an official government service.')}</span><a href="index.html">${t('Se alle 5 koncepter','Explore all 5 concepts')} ↗</a></footer>`;}
function sources(){return `<details class="source-box" id="sources"><summary>${icon('book')}${t('Rådene bag prototypen','The guidance behind the prototype')}</summary><p>${t('Baseret på offentlige råd fra Beredskabsstyrelsen og Styrelsen for Samfundssikkerhed. Kilder gennemgået 20. oktober 2026. Følg altid myndighedernes aktuelle anvisninger.','Based on public guidance from the Danish Emergency Management Agency and the Danish Agency for Resilience. Sources reviewed 20 October 2026. Always follow current official instructions.')}</p><div class="source-list"><a href="https://samsik.dk/forberedt/" target="_blank" rel="noopener">SAMSIK · Forberedt på kriser ↗</a><a href="https://www.brs.dk/en/prepared/" target="_blank" rel="noopener">DEMA · Prepared for crises (English) ↗</a><a href="https://www.brs.dk/da/sirenen/om-varsling/" target="_blank" rel="noopener">Beredskabsstyrelsen · S!RENEN ↗</a><a href="https://mst.dk/borger/sundhed-og-kemi/forberedt-paa-kriser" target="_blank" rel="noopener">Miljøstyrelsen · ${t('Rent drikkevand','Drinking water')} ↗</a><a href="https://foedevarestyrelsen.dk/kost-og-foedevarer/foedevaresikkerhed/foedevareberedskab/forberedt-paa-kriser" target="_blank" rel="noopener">${t('Fødevarestyrelsen · Mad og opbevaring','Danish food authority · Food and storage')} ↗</a></div></details>`;}
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3500);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function offlineDownload(){download(location.pathname.split('/').pop()||'guide.html','<!DOCTYPE html>\n'+document.documentElement.outerHTML,'text/html');toast(t('HTML-filen er hentet. Åbn den uden internet. Fremdrift er knyttet til browseren.','HTML downloaded. Open it without internet. Progress stays with this browser.'));}
function updatePage(){document.documentElement.lang=lang;render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-lang]');if(b){const old=b.dataset.lang;lang=old;save('prepared-language',lang);updatePage();document.querySelector(`[data-lang="${old}"]`)?.focus();}});
const today=()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate());};
const dateIn=days=>{const d=today();d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const daysUntil=date=>Math.round((new Date(date+'T00:00:00')-today())/86400000);
const displayDate=date=>new Intl.DateTimeFormat(lang==='da'?'da-DK':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(date+'T00:00:00'));
'''.replace('__ICONS__', json.dumps(ICONS,ensure_ascii=False))

def write_app(filename,title,css,script):
    html=f'''<!DOCTYPE html>
<html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Fem interaktive danske beredskabskoncepter med dansk og engelsk sprogvalg."><meta name="theme-color" content="#17263c"><title>{title}</title><style>{BASE_CSS}\n{css}</style></head><body><div id="app"></div><noscript>Denne interaktive prototype kræver JavaScript. This prototype requires JavaScript. Se officielle råd: https://samsik.dk/forberedt/</noscript><script>{RUNTIME}\n{script}\nupdatePage();</script></body></html>'''
    (ROOT/filename).write_text(html,encoding='utf-8')

