KLAR_JS=r'''
const KEY='prepared-klar-v1';
let state=read(KEY,{people:2,checked:[]});
if(!state||!Array.isArray(state.checked))state={people:2,checked:[]};
state.people=Math.min(12,Math.max(1,Number(state.people)||2));
let filter='all';
const tasks=[
['water','drop','Vand','Water','Drikkevand til tre døgn','Drinking water for three days','3 liter pr. person pr. døgn. Husdyr kommer oveni.','3 litres per person per day. Add water for pets.'],
['food','box','Mad','Food','Mad, der holder sig','Food that keeps','Vælg mad til tre døgn, som I kan lide.','Choose food for three days that you enjoy.'],
['medicine','heart','Sundhed','Health','Medicin og førstehjælp','Medicine and first aid','Planlæg nødvendig medicin og en førstehjælpskasse.','Plan essential medicine and a first-aid kit.'],
['hygiene','drop','Hygiejne','Hygiene','Hygiejneartikler','Hygiene supplies','Toiletpapir, poser og håndhygiejne.','Toilet paper, bags and hand hygiene.'],
['warmth','sun','Varme','Warmth','Tæpper og varmt tøj','Blankets and warm clothes','Saml det, I allerede har derhjemme.','Gather what you already have at home.'],
['power','bolt','Strøm','Power','Lys og opladet powerbank','Light and a charged power bank','Find lommelygte, batterier og powerbank.','Find a torch, batteries and a power bank.'],
['radio','radio','Information','Information','FM-radio','FM radio','Batteri, håndsving eller solceller.','Battery, hand-crank or solar powered.'],
['payment','box','Betaling','Payments','Betaling uden mobilen','Paying without your phone','Hav et fysisk betalingskort og overvej lidt kontanter.','Have a physical payment card and consider some cash.'],
['plan','people','Aftaler','Plans','En aftale med dine nærmeste','A plan with those close to you','Skriv vigtige numre ned, og tal om hjælp.','Write down important numbers and discuss help.']
];
function persist(){save(KEY,state);}
function render(){
const n=tasks.filter(x=>state.checked.includes(x[0])).length,pct=Math.round(n/tasks.length*100);
const next=tasks.find(x=>!state.checked.includes(x[0]));
const visible=tasks.filter(x=>filter==='all'||(filter==='todo'?!state.checked.includes(x[0]):state.checked.includes(x[0])));
document.title=t('Klar72 · Dit hjemmeberedskab','Klar72 · Your home preparedness');
document.getElementById('app').innerHTML=header('klar<span style="font-weight:400">72</span>','shield',`<a href="#sources">${t('Officielle råd','Official guidance')}</a>`)+`<div class="layout"><aside class="sidebar"><button class="active" onclick="document.getElementById('main').scrollIntoView()">${icon('home')}${t('Mit overblik','My overview')}</button><button onclick="document.getElementById('checklist').scrollIntoView()">${icon('check')}${t('Min tjekliste','My checklist')}</button><button onclick="document.getElementById('household').scrollIntoView()">${icon('people')}${t('Min husstand','My household')}</button><button onclick="document.getElementById('sources').open=true;document.getElementById('sources').scrollIntoView()">${icon('book')}${t('Viden & råd','Knowledge & advice')}</button><div class="side-note">${icon('shield')}<strong>${t('Lidt forberedelse. Mere ro.','A little preparation. More peace of mind.')}</strong><p class="subtle">${t('Tag ét skridt ad gangen. Du behøver ikke købe alt på én gang.','Take one step at a time. You do not need to buy everything at once.')}</p></div></aside><main class="main-klar" id="main"><div class="row between greeting wrap"><div><div class="eyebrow">${t('Dit personlige beredskab','Your personal preparedness')}</div><h1>${t('Godt at være forberedt.','It feels good to be prepared.')}</h1></div></div><section class="hero-klar"><div><div class="eyebrow">${t('Klar til 3 døgn','Prepared for 3 days')}</div><h2>${t('Små skridt.<br>En tryggere hverdag.','Small steps.<br>A calmer everyday life.')}</h2><p>${t('Få styr på det vigtigste for din husstand. Din tjekliste følger med dig her.','Take care of the essentials for your household. Keep your personal checklist here.')}</p><a class="btn" style="background:#fff;color:#1c2d43;border-color:#fff" href="#checklist">${t('Fortsæt min forberedelse','Continue preparing')}${icon('arrow')}</a></div><div class="ring" style="--value:${pct}" role="img" aria-label="${pct}% ${t('af punkterne markeret','of items checked')}"><div><strong>${pct}%</strong><small>${n} ${t('af','of')} ${tasks.length} ${t('punkter','items')}</small></div></div></section><div class="grid3 stats"><div class="card stat"><span class="tile">${icon('people')}</span><div><strong>${state.people}</strong><p class="subtle">${t('i husstanden','in your household')}</p></div></div><div class="card stat"><span class="tile">${icon('drop')}</span><div><strong>${state.people*9} L</strong><p class="subtle">${t('vand til 3 døgn','water for 3 days')}</p></div></div><div class="card stat"><span class="tile">${icon('clock')}</span><div><strong>72 <small>${t('timer','hours')}</small></strong><p class="subtle">${t('anbefalet beredskab','recommended supplies')}</p></div></div></div><div class="klar-content"><section class="card" id="checklist"><div class="row between section-head"><h2>${t('Din tjekliste','Your checklist')}</h2><button class="btn quiet" onclick="exportChecklist()">${icon('download')}<span>${t('Hent','Export')}</span></button></div><div class="chips">${[['all','Alle','All'],['todo','Mangler','To do'],['done','På plads','Done']].map(x=>`<button class="chip ${filter===x[0]?'active':''}" onclick="filter='${x[0]}';updatePage()" aria-pressed="${filter===x[0]}">${t(x[1],x[2])}</button>`).join('')}</div><div style="margin-top:10px">${visible.length?visible.map(x=>`<label class="check-row"><input type="checkbox" data-task="${x[0]}" ${state.checked.includes(x[0])?'checked':''}><span><strong>${t(x[4],x[5])}</strong><span class="subtle muted">${t(x[6],x[7])}</span></span></label>`).join(''):`<div class="empty">${t('Ingen punkter her endnu.','No items here yet.')}</div>`}</div><div class="notice" style="margin-top:20px">${t('Fremdriften viser dine markeringer — den er ikke en vurdering af din sikkerhed.','Progress reflects your checkmarks — it is not a safety assessment.')}</div></section><aside class="stack" style="align-content:start"><section class="card water-card" id="household"><div class="row between"><h3>${t('Vand til din husstand','Water for your household')}</h3>${icon('drop')}</div><div class="water-number numeric">${state.people*9}<span style="font-size:23px;margin-left:7px">${t('liter','litres')}</span></div><p class="subtle">${state.people} × 3 ${t('døgn','days')} × 3 ${t('liter','litres')}</p><div class="water-graphic" aria-hidden="true">${'<i></i>'.repeat(9)}</div><div class="house-count"><span class="subtle">${t('Personer i husstanden','People in your household')}</span><div class="counter"><button class="square" onclick="people(-1)" aria-label="${t('Færre personer','Fewer people')}" ${state.people<=1?'disabled':''}>${icon('minus')}</button><strong>${state.people}</strong><button class="square" onclick="people(1)" aria-label="${t('Flere personer','More people')}" ${state.people>=12?'disabled':''}>${icon('plus')}</button></div></div><p class="subtle">${t('Til drikke og eventuel madlavning. Beregn ekstra til kæledyr efter deres behov.','For drinking and possible food preparation. Add water for pets according to their needs.')}</p></section><section class="card next-card"><div class="eyebrow">${t('Dit næste lille skridt','Your next small step')}</div><h3>${next?t(next[4],next[5]):t('Gennemgå dit beredskab løbende','Review your supplies regularly')}</h3><p>${next?t(next[6],next[7]):t('Tjek holdbarheder og aftaler. Behov kan ændre sig.','Check expiry dates and plans. Needs can change.')}</p><a class="btn quiet" href="#checklist">${t('Til tjeklisten','Open checklist')}${icon('arrow')}</a></section></aside></div>${sources()}<p class="subtle muted" style="margin-top:20px">${t('Dine markeringer gemmes kun i denne browser.','Your checkmarks are saved only in this browser.')}</p></main></div>`+footer();
document.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{const id=el.dataset.task;state.checked=el.checked?[...new Set([...state.checked,id])]:state.checked.filter(x=>x!==id);persist();updatePage();document.querySelector(`[data-task="${id}"]`)?.focus();});
}
function people(delta){state.people=Math.min(12,Math.max(1,state.people+delta));persist();updatePage();}
function exportChecklist(){download('klar72-'+lang+'.txt',t('Min tjekliste til 3 døgn','My three-day checklist')+'\n'+state.people+' '+t('personer','people')+' · '+state.people*9+' L\n\n'+tasks.map(x=>(state.checked.includes(x[0])?'[x] ':'[ ] ')+t(x[4],x[5])).join('\n')+'\n\nhttps://samsik.dk/forberedt/');}
'''
write_app('01-klar72.html','Klar72 · Dit hjemmeberedskab',KLAR_CSS,KLAR_JS)

SKAB_CSS=r'''
:root{--bg:#f6f6ef;--ink:#253b2e;--accent:#3b6148;--muted:#707b6c;--line:#dfe3d8;--soft:#e8eddf;--card:#fffefa}.topbar{background:var(--bg)}.skab-hero{display:grid;grid-template-columns:1.15fr 1fr;gap:40px;align-items:center;padding:10px 0 34px}.skab-hero h1{max-width:510px}.shelf-art{width:100%;max-height:260px}.skab-stats{margin:6px 0 35px}.skab-stats .card{border-radius:12px;display:flex;gap:20px;align-items:center}.skab-stats .icon{color:var(--accent)}.inventory-layout{display:grid;grid-template-columns:1fr 310px;gap:25px}.inventory{display:grid;gap:12px}.item{display:grid;grid-template-columns:48px 1fr auto;gap:17px;align-items:center;padding:20px;border:1px solid var(--line);border-radius:13px;background:var(--card)}.item-art{width:48px;height:57px;display:grid;place-items:center;background:var(--soft);border-radius:9px;color:var(--accent)}.item h3{font-size:15px}.item .date{display:inline-block;font-size:11px;margin-top:9px}.expiry{color:#946638;background:#f7ecdb;padding:3px 8px;border-radius:5px}.expired{color:#9d3d35;background:#fae9e5;padding:3px 8px;border-radius:5px}.stock-control{display:flex;align-items:center;gap:12px}.stock-control button{width:30px;height:32px;min-width:30px}.stock-control strong{font-size:16px;min-width:30px;text-align:center}.shopping{background:#e9efdf}.shopping h2{font-size:22px}.shopping-row{display:flex;justify-content:space-between;gap:10px;padding:16px 0;border-bottom:1px solid #d4ddca;font-size:13px}.shopping-row:last-of-type{border:0}.search-wrap{position:relative}.search-wrap input{width:100%;height:45px;padding:10px 12px 10px 40px;border-radius:9px;border:1px solid var(--line);background:var(--card);color:var(--ink)}.search-wrap>.icon{position:absolute;left:12px;top:12px;width:18px}.item-actions{display:grid;justify-items:end;gap:4px}.delete-btn{border:0;background:none;color:var(--muted);font-size:10px;padding:5px}.skab-stats .kpi{font-size:28px}.inventory-tools{margin-bottom:20px}.person-select{max-width:80px}.no-stock{background:#f7ecdb;color:#946638}.rotation h3{font-size:15px}.rotation p{font-size:12px;margin:10px 0 16px}.inventory-title{font-size:26px}.shelf-line{stroke:#c1cbb4;stroke-width:7;stroke-linecap:round}
@media(max-width:950px){.inventory-layout{grid-template-columns:1fr 270px}.item{gap:12px;padding:15px}.item-art{width:40px}.item{grid-template-columns:40px 1fr auto}.stock-control{gap:7px}.skab-hero{gap:15px}.skab-stats .card{padding:18px;gap:12px}}
@media(max-width:720px){.skab-hero{grid-template-columns:1fr}.shelf-art{max-height:190px}.inventory-layout{grid-template-columns:1fr}.skab-stats{grid-template-columns:1fr}.skab-stats .card{padding:15px}.item{grid-template-columns:36px 1fr auto;gap:10px}.item-art{width:36px;height:46px}.stock-control{gap:5px}.stock-control button{min-width:28px;width:28px}.stock-control strong{min-width:25px}.item h3{font-size:13px}}
'''

SKAB_JS=r'''
const KEY='prepared-skab-v1';
const defaults=()=>({people:2,items:[{id:'water',da:'Drikkevand',en:'Drinking water',cat:'water',qty:12,target:9,unit:'L',date:dateIn(120),custom:false},{id:'crisp',da:'Knækbrød',en:'Crispbread',cat:'food',qty:2,target:2,unit:'pack',date:dateIn(12),custom:false},{id:'beans',da:'Spiseklare bønner',en:'Ready-to-eat beans',cat:'food',qty:3,target:2,unit:'can',date:dateIn(240),custom:false},{id:'nuts',da:'Nødder',en:'Nuts',cat:'food',qty:1,target:1,unit:'pack',date:dateIn(90),custom:false},{id:'batteries',da:'Batterier',en:'Batteries',cat:'gear',qty:1,target:1,unit:'pack',date:'',custom:false}]});
let state=read(KEY,defaults());if(!state||!Array.isArray(state.items))state=defaults();
let filter='all',search='',sort='category';
const unit=u=>u==='L'?'L':u==='pack'?t('pk.','packs'):u==='can'?t('dåser','cans'):t('stk.','items');
const catName=c=>c==='water'?t('Vand','Water'):c==='food'?t('Mad','Food'):t('Udstyr','Equipment');
const itemName=x=>t(x.da,x.en);
const deficits=()=>state.items.map(x=>({...x,missing:Math.max(0,x.target*state.people-x.qty)})).filter(x=>x.missing);
function render(){
const water=state.items.find(x=>x.id==='water'),soon=state.items.filter(x=>x.date&&daysUntil(x.date)<=30).length;
let items=state.items.filter(x=>(filter==='all'||x.cat===filter||filter==='soon'&&x.date&&daysUntil(x.date)<=30)&&itemName(x).toLowerCase().includes(search.toLowerCase()));
if(sort==='expiry')items=[...items].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));
const art=`<svg class="shelf-art" viewBox="0 0 480 270" aria-hidden="true"><circle cx="260" cy="130" r="125" fill="#e8eddf"/><path d="M50 236h385" class="shelf-line"/><rect x="92" y="102" width="74" height="130" rx="12" fill="#aac2ba"/><rect x="109" y="78" width="40" height="29" rx="6" fill="#49685e"/><rect x="92" y="145" width="74" height="53" fill="#dbe8e1"/><path d="M124 158s-12 14-12 20a12 12 0 0 0 24 0c0-6-12-20-12-20" fill="#789c92"/><rect x="185" y="136" width="79" height="97" rx="8" fill="#bf7855"/><rect x="185" y="128" width="79" height="12" rx="5" fill="#93977f"/><rect x="185" y="160" width="79" height="47" fill="#eee2be"/><path d="M217 173q-16 12 2 24 19-13 9-23" fill="#65774e"/><path d="m279 82 72-6 12 157h-92Z" fill="#d4b68e"/><path d="m280 95 73-5M277 213h85" stroke="#b7986e" stroke-width="3"/><path d="m292 124 43-4M293 133l34-3" stroke="#eee6cf" stroke-width="5"/><ellipse cx="316" cy="166" rx="20" ry="23" fill="#f4eddb"/><path d="m303 166 9 9 16-19" stroke="#8b9a72" stroke-width="4" fill="none"/><rect x="376" y="157" width="46" height="76" rx="9" fill="#6c7b55"/><path d="M386 147h26v13h-26Z" fill="#bec9a6"/><path d="M390 181h19m-19 8h19" stroke="#d6dec5" stroke-width="3"/><path d="m73 59 4-15 12 9M385 75l11-11m-2 15 16 1" stroke="#a9b99b" stroke-width="3" fill="none"/></svg>`;
document.title=t('Skab · Dit lille beredskabslager','Skab · Your home supply shelf');
document.getElementById('app').innerHTML=header('skab.','leaf',`<a href="#inventory">${t('Mit lager','My supplies')}</a><a href="#shopping">${t('Indkøbsliste','Shopping list')}</a>`)+`<main class="page" id="main"><section class="skab-hero"><div><div class="eyebrow">${t('Et beredskab, der passer ind','Preparedness that fits your life')}</div><h1>${t('Et lille lager.<br>Mere ro.','A small shelf.<br>More peace of mind.')}</h1><p class="lead">${t('Brug det, du har. Fyld op lidt ad gangen. Hold styr på dine forsyninger til tre døgn.','Use what you have. Top up a little at a time. Keep track of your supplies for three days.')}</p><div class="row" style="margin-top:23px"><button class="btn primary" onclick="openItem()">${icon('plus')}${t('Tilføj en vare','Add an item')}</button><span class="subtle muted">${t('Eksempeldata · redigér frit','Sample data · make it yours')}</span></div></div>${art}</section><div class="grid3 skab-stats"><div class="card">${icon('drop','big')}<div><div class="kpi numeric">${water?water.qty:0} / ${state.people*9} L</div><p class="subtle">${t('drikkevand i dit lager','drinking water in your supplies')}</p></div></div><div class="card">${icon('box','big')}<div><div class="kpi">${state.items.length} ${t('varer','items')}</div><p class="subtle">${t('et lille overblik, der hjælper','a little overview that helps')}</p></div></div><div class="card">${icon('clock','big')}<div><div class="kpi">${soon} ${t('snart','soon')}</div><p class="subtle">${t('med dato inden for 30 dage','with a date within 30 days')}</p></div></div></div><div class="row between section-head wrap"><h2 class="inventory-title" id="inventory">${t('Din beredskabshylde','Your preparedness shelf')}</h2><label class="row subtle">${t('Personer','People')}<select class="person-select" aria-label="${t('Personer i husstanden','People in household')}" onchange="state.people=Number(this.value);persist()" style="padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--card)">${Array.from({length:12},(_,i)=>`<option ${state.people===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label></div><div class="inventory-layout"><section><div class="stack inventory-tools"><div class="row wrap between"><div class="chips">${[['all','Alt','All'],['food','Mad','Food'],['water','Vand','Water'],['gear','Udstyr','Equipment'],['soon','Brug snart','Use soon']].map(x=>`<button class="chip ${filter===x[0]?'active':''}" aria-pressed="${filter===x[0]}" onclick="filter='${x[0]}';updatePage()">${t(x[1],x[2])}</button>`).join('')}</div><label class="sr-only" for="sort">${t('Sortering','Sort order')}</label><select id="sort" onchange="sort=this.value;updatePage()" style="border:0;background:none;color:var(--muted);padding:10px 0"><option value="category">${t('Standard','Default')}</option><option value="expiry" ${sort==='expiry'?'selected':''}>${t('Nærmeste dato','Earliest date')}</option></select></div><label class="search-wrap">${icon('search')}<span class="sr-only">${t('Søg i lager','Search supplies')}</span><input id="search" type="search" value="${esc(search)}" placeholder="${t('Find en vare på din hylde…','Find an item on your shelf…')}" oninput="search=this.value;refreshSearch()"></label></div><div class="inventory" id="items">${itemsHTML(items)}</div></section><aside class="stack" style="align-content:start"><section class="card shopping" id="shopping"><div class="row between"><h2>${t('Det mangler du','Your next top-ups')}</h2>${icon('box')}</div><p class="subtle" style="margin:10px 0 6px">${t('Beregnet ud fra dine valgte mål.','Calculated from your chosen targets.')}</p>${deficits().length?deficits().map(x=>`<div class="shopping-row"><span>${esc(itemName(x))}</span><strong>${x.missing} ${unit(x.unit)}</strong></div>`).join(''):`<p style="padding:20px 0">${t('Alle valgte mål er nået.','All chosen targets reached.')}</p>`}<button class="btn primary" style="width:100%;margin-top:20px" onclick="exportShopping()">${icon('download')}${t('Hent indkøbsliste','Download shopping list')}</button><p class="subtle" style="margin-top:15px">${t('Vand: 9 L pr. person til tre døgn. Madmængder er redigerbare eksempler, ikke en komplet kostplan.','Water: 9 L per person for three days. Food targets are editable examples, not a complete meal plan.')}</p></section><section class="card rotation"><span class="badge">${icon('leaf')}${t('Mindre spild','Less waste')}</span><h3 style="margin-top:17px">${t('Lad lageret blive en del af hverdagen.','Make your supplies part of everyday life.')}</h3><p>${t('Brug de ældste varer først. Fyld op igen, når du handler. Opbevar vand mørkt og køligt i egnede beholdere.','Use older items first. Replenish when you shop. Store water in a cool, dark place in suitable containers.')}</p><a class="btn quiet" href="#sources">${t('Læs rådene','Read the guidance')}${icon('arrow')}</a></section></aside></div><p class="subtle muted" style="margin-top:22px">${t('Kun lokal lagring. Ingen påmindelser sendes. Datoer kontrolleres, når du åbner siden.','Local storage only. No reminders are sent. Dates are checked when you open this page.')}</p>${sources()}</main>`+footer()+`<dialog id="item-dialog"><form id="item-form"><div class="row between"><h2 id="dialog-title"></h2><button class="square" type="button" onclick="document.getElementById('item-dialog').close()" aria-label="${t('Luk','Close')}">${icon('close')}</button></div><input type="hidden" id="item-id"><label class="field">${t('Varenavn','Item name')}<input id="item-name" maxlength="70" required></label><div class="grid2"><label class="field">${t('Kategori','Category')}<select id="item-cat"><option value="food">${t('Mad','Food')}</option><option value="water">${t('Vand','Water')}</option><option value="gear">${t('Udstyr','Equipment')}</option></select></label><label class="field">${t('Enhed','Unit')}<select id="item-unit"><option value="each">${t('Styk','Items')}</option><option value="L">Liter</option><option value="pack">${t('Pakker','Packs')}</option><option value="can">${t('Dåser','Cans')}</option></select></label><label class="field">${t('På lager','In stock')}<input id="item-qty" type="number" min="0" max="100000" step="0.5" required></label><label class="field">${t('Dit mål pr. person','Your target per person')}<input id="item-target" type="number" min="0" max="100000" step="0.5" required></label></div><label class="field">${t('Bedst før / dato for gennemgang','Best before / review date')}<input id="item-date" type="date"></label><p class="subtle">${t('Brug etikettens dato eller vælg din egen gennemgangsdato.','Use the date on the label or choose your own review date.')}</p><button class="btn primary" type="submit">${t('Gem vare','Save item')}</button></form></dialog>`;
document.getElementById('item-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('item-name').value.trim();if(!name)return;const id=document.getElementById('item-id').value;const old=state.items.find(x=>x.id===id);const item={id:id||'item-'+Date.now(),da:old&&name===itemName(old)?old.da:name,en:old&&name===itemName(old)?old.en:name,cat:document.getElementById('item-cat').value,unit:document.getElementById('item-unit').value,qty:Number(document.getElementById('item-qty').value),target:Number(document.getElementById('item-target').value),date:document.getElementById('item-date').value,custom:old?old.custom:true};state.items=old?state.items.map(x=>x.id===id?item:x):[...state.items,item];persist();toast(t('Varen er gemt','Item saved'));};
}
function itemsHTML(items){return items.length?items.map(x=>{const days=x.date?daysUntil(x.date):9999;return `<article class="item"><div class="item-art">${icon(x.cat==='water'?'drop':x.cat==='food'?'box':'bolt','big')}</div><div><h3>${esc(itemName(x))}</h3><span class="subtle muted">${catName(x.cat)} · ${t('Mål','Target')}: ${x.target*state.people} ${unit(x.unit)}</span><br>${x.date?`<span class="date ${days<0?'expired':days<=30?'expiry':'muted'}">${days<0?t('Dato passeret · ','Date passed · '):days<=30?t('Brug / gennemgå snart · ','Use / review soon · '):''}${displayDate(x.date)}</span>`:''}</div><div class="item-actions"><div class="stock-control"><button class="square" onclick="quantity('${x.id}',-1)" aria-label="${t('Fjern én','Remove one')} ${esc(itemName(x))}" ${x.qty<=0?'disabled':''}>${icon('minus')}</button><strong>${x.qty}</strong><button class="square" onclick="quantity('${x.id}',1)" aria-label="${t('Tilføj én','Add one')} ${esc(itemName(x))}">${icon('plus')}</button></div><button class="delete-btn" onclick="openItem('${x.id}')">${t('Redigér','Edit')}</button>${x.custom?`<button class="delete-btn" onclick="removeItem('${x.id}')">${t('Slet','Delete')}</button>`:''}</div></article>`;}).join(''):`<div class="card empty">${t('Ingen varer matcher dit valg.','No items match your selection.')}</div>`;}
function refreshSearch(){const input=document.getElementById('search'),pos=input.selectionStart;updatePage();const fresh=document.getElementById('search');fresh.focus();try{fresh.setSelectionRange(pos,pos);}catch{}}
function persist(){save(KEY,state);updatePage();}
function quantity(id,delta){const x=state.items.find(x=>x.id===id);x.qty=Math.max(0,x.qty+delta);persist();}
function removeItem(id){state.items=state.items.filter(x=>x.id!==id);persist();toast(t('Varen er fjernet','Item removed'));}
function openItem(id=''){const x=state.items.find(x=>x.id===id);document.getElementById('dialog-title').textContent=x?t('Redigér vare','Edit item'):t('Ny vare på hylden','New item on your shelf');document.getElementById('item-id').value=id;document.getElementById('item-name').value=x?itemName(x):'';document.getElementById('item-cat').value=x?.cat||'food';document.getElementById('item-unit').value=x?.unit||'each';document.getElementById('item-qty').value=x?.qty??0;document.getElementById('item-target').value=x?.target??1;document.getElementById('item-date').value=x?.date||'';document.getElementById('item-dialog').showModal();}
function exportShopping(){download('skab-'+lang+'.txt',t('Min indkøbsliste','My shopping list')+'\n'+state.people+' '+t('personer','people')+'\n\n'+(deficits().map(x=>`[ ] ${itemName(x)}: ${x.missing} ${unit(x.unit)}`).join('\n')||t('Alle valgte mål er nået.','All chosen targets reached.'))+'\n\n'+t('Madmængder er eksempler. Tilpas til din husstand.','Food quantities are examples. Adapt to your household.')+'\nhttps://samsik.dk/forberedt/');}
'''
write_app('02-skab.html','Skab · Dit beredskabslager',SKAB_CSS,SKAB_JS)

ROLIG_CSS=r'''
:root{--bg:#101c2c;--ink:#edf1f7;--accent:#f2b868;--on-accent:#142236;--soft:#26364b;--line:#304053;--muted:#a9b7c8;--card:#1a2a3e}.topbar{background:var(--bg)}.brand-mark{background:#f2b868;color:#142236}.rolig-page{max-width:1180px}.exercise{color:#f2b868;background:#f2b86812;border:1px solid #f2b86835;margin-bottom:42px}.rolig-hero{display:grid;grid-template-columns:1fr 200px;gap:35px;align-items:center;margin-bottom:35px}.rolig-hero h1{font-size:clamp(40px,6vw,65px);max-width:620px}.orbit{width:180px;height:180px;position:relative;border:1px solid #35465b;border-radius:50%;display:grid;place-items:center}.orbit:before{content:'';position:absolute;inset:19px;border:1px dashed #496077;border-radius:50%}.orbit .icon{width:65px;height:65px;color:var(--accent)}.orbit i{position:absolute;width:11px;height:11px;background:var(--accent);border-radius:50%;top:30px;right:15px}.scenario-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:34px}.scenario-tab{display:flex;align-items:center;gap:13px;padding:20px;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:12px;min-height:89px}.scenario-tab.active{border-color:var(--accent);background:#f2b8680d}.scenario-tab.active .icon{color:var(--accent)}.scenario-tab strong{font-size:14px;display:block}.scenario-tab small{color:var(--muted);font-size:11px}.guide-layout{display:grid;grid-template-columns:240px 1fr;gap:25px}.guide-index{padding:18px 0}.guide-index button{display:flex;gap:13px;align-items:center;text-align:left;width:100%;padding:14px;border:0;border-radius:9px;color:var(--muted);background:none;font-size:12px;margin:3px 0}.guide-index button.active{background:#25374c;color:#fff}.guide-index button span{width:26px;height:26px;flex-shrink:0;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;font-size:11px}.guide-index button.active span{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}.guide-step{padding:34px;border-radius:18px}.step-top{margin-bottom:30px}.guide-step h2{font-size:32px;letter-spacing:-1px;max-width:500px}.guide-step .description{font-size:16px;line-height:1.8;margin:20px 0 26px}.guide-step .check-row{padding:17px 0}.guide-step .check-row strong{font-size:14px}.guide-step .check-row input{background:var(--bg);border-color:#708097}.guide-step .notice{margin:26px 0;color:#e6c9a3;background:#f2b8680d;border:1px solid #f2b86830}.guide-buttons{margin-top:28px}.trusted{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:30px}.trusted a{padding:18px;border:1px solid var(--line);border-radius:12px;text-decoration:none;font-weight:600;font-size:14px}.trusted a small{display:block;font-size:10px;color:var(--muted);font-weight:400;margin-top:3px}.rolig-bottom{margin-top:28px;padding:18px 0;font-size:12px}.rolig-page .field input{color:var(--ink)}
@media(max-width:750px){.guide-layout{grid-template-columns:1fr}.guide-index{display:flex;gap:5px;padding:0}.guide-index button{padding:10px;justify-content:center}.guide-index button b{display:none}.guide-index button span{width:29px;height:29px}.scenario-tab{padding:15px;display:block}.scenario-tab>.icon{margin-bottom:10px}.scenario-tabs{gap:8px}.scenario-tab strong{font-size:12px}.scenario-tab small{font-size:10px}.rolig-hero{grid-template-columns:1fr}.orbit{display:none}.guide-step{padding:25px}.guide-step h2{font-size:27px}.guide-step .description{font-size:14px}.trusted{gap:7px}.trusted a{padding:13px;font-size:12px}.exercise{margin-bottom:28px}}
'''

ROLIG_JS=r'''
const KEY='prepared-rolig-v1';
let state=read(KEY,{scenario:'power',step:0,done:{}});if(!state||!state.done)state={scenario:'power',step:0,done:{}};
const scenarios={
power:{icon:'bolt',title:['Strømmen går','Power outage'],sub:['Øv din plan uden strøm','Practise your power-outage plan'],steps:[
{title:['Find ro og lys','Find calm and light'],desc:['Forestil dig en aften uden strøm. Start med at finde din lommelygte og holde dig orienteret.','Imagine an evening without electricity. Start by finding your torch and staying informed.'],tasks:[['Find lommelygte og batterier','Find a torch and batteries'],['Find powerbank og FM-radio','Find your power bank and FM radio']],note:['Brug aldrig grill eller stormkøkken indendørs eller i helt eller delvist lukkede rum. Risiko for kulilteforgiftning.','Never use a grill or camping stove indoors or in fully or partially enclosed spaces. Risk of carbon monoxide poisoning.']},
{title:['Få overblik over mad og vand','Check your food and water'],desc:['Du kan mangle adgang til både madlavning og indkøb. Brug din plan for tre døgn, og tænk på alles behov.','Cooking and shopping may be disrupted. Use your three-day plan and consider everyone’s needs.'],tasks:[['Find mad, der kan spises uden tilberedning','Find food that needs no cooking'],['Tjek drikkevand: 9 liter pr. person til tre døgn','Check drinking water: 9 litres per person for three days'],['Undgå at åbne køleskab og fryser unødigt','Avoid opening the fridge and freezer unnecessarily']],note:['Tilpas forsyninger til børn, særlige kostbehov og kæledyr.','Adapt supplies for children, special dietary needs and pets.']},
{title:['Hold forbindelsen','Stay connected'],desc:['Telefonnet og internet kan blive påvirket. Aftal, hvordan I finder hinanden, og hvor I får troværdig information.','Phone networks and internet may be affected. Agree how to find each other and where to get reliable information.'],tasks:[['Skriv vigtige telefonnumre ned','Write down important phone numbers'],['Aftal kontakt med dine nærmeste','Agree how to contact those close to you'],['Find en FM-radio til myndighedsmeddelelser','Find an FM radio for official messages']],note:['Kontrollér afsenderen, før du deler en meddelelse.','Check the source before sharing a message.']}
]},
water:{icon:'drop',title:['Vandet forsvinder','Water disruption'],sub:['Forbered dig på tomme haner','Prepare for empty taps'],steps:[
{title:['Find dit drikkevand','Find your drinking water'],desc:['Regn med tre liter pr. person pr. døgn til drikke og eventuel madlavning. Til tre døgn er det ni liter pr. person.','Allow three litres per person per day for drinking and possible cooking. That is nine litres per person for three days.'],tasks:[['Find husstandens vandlager','Locate your household’s water supplies'],['Beregn ekstra vand til kæledyr','Allow extra water for pets']],note:['Vand opbevares mørkt og køligt i rene beholdere godkendt til fødevarer.','Store water in a cool, dark place in clean, food-safe containers.']},
{title:['Følg de lokale anvisninger','Follow local instructions'],desc:['Find information hos kommunen eller dit vand- og spildevandsselskab. Anvisninger afhænger af den konkrete hændelse.','Check your municipality or local water and wastewater utility. Instructions depend on the specific incident.'],tasks:[['Find dit vandværks hjemmeside','Find your water utility’s website'],['Find kommunens informationskanal','Find your municipality’s information channel']],note:['Antag ikke, at kogning gør alt vand sikkert. Følg myndighedernes konkrete anvisninger.','Do not assume boiling makes all water safe. Follow the specific official instructions.']},
{title:['Planlæg hygiejnen','Plan for hygiene'],desc:['En afbrydelse kan også påvirke toilet og afløb. Hav hygiejneartikler klar, og følg de lokale råd.','A disruption can also affect toilets and drains. Keep hygiene supplies ready and follow local guidance.'],tasks:[['Find toiletpapir og solide affaldsposer','Find toilet paper and strong waste bags'],['Planlæg håndhygiejne ved vandmangel','Plan hand hygiene when water is unavailable']],note:['Læs Miljøstyrelsens vejledning om toiletforhold og hygiejne via kilderne nedenfor.','Read the Danish environmental authority’s guidance on toilets and hygiene in the sources below.']}
]},
siren:{icon:'radio',title:['Sirenen lyder','The siren sounds'],sub:['Kend myndighedernes råd','Know the official advice'],steps:[
{title:['Gå indenfor','Go indoors'],desc:['Hører du en fysisk varslingssirene, skal du gå indenfor og søge information hos DR eller TV 2.','If you hear a physical warning siren, go indoors and seek information from DR or TV 2.'],tasks:[['Udpeg et sted indenfor, hvor du kan søge information','Choose an indoor place to get information']],note:['Dette er en øvelse. Prototypen modtager eller udsender ingen varsler.','This is a practice exercise. This prototype does not receive or issue warnings.']},
{title:['Stop. Læs. Reagér.','Stop. Read. Respond.'],desc:['Modtager du S!RENEN på mobilen, så stop det, du er i gang med, læs meddelelsen og følg dens anvisninger.','If you receive S!RENEN on your phone, stop what you are doing, read the message and follow its instructions.'],tasks:[['Tal med husstanden om at læse hele varslingen','Discuss reading the entire warning with your household'],['Find ud af, hvor I søger mere information','Agree where to seek further information']],note:['Den konkrete varsling fortæller dig, hvordan du skal handle.','The specific warning tells you how to act.']},
{title:['Brug troværdige kilder','Use trustworthy sources'],desc:['Søg information hos DR, TV 2 og myndighederne. Brug FM-radio, hvis andre informationskanaler svigter.','Seek information from DR, TV 2 and the authorities. Use FM radio if other information channels fail.'],tasks:[['Find DR eller TV 2 på din foretrukne enhed','Find DR or TV 2 on your preferred device'],['Aftal at kontrollere kilder, før I deler information','Agree to check sources before sharing information']],note:['Ring kun 1-1-2 ved en akut nødsituation med behov for ambulance, politi eller brandvæsen.','Call 1-1-2 only in an emergency requiring ambulance, police or fire services.']}
]}
};
if(!scenarios[state.scenario])state.scenario='power';state.step=Math.min(2,Math.max(0,Number(state.step)||0));
function render(){const s=scenarios[state.scenario],step=s.steps[state.step],id=state.scenario+'-'+state.step;const checked=state.done[id]||[];
document.title=t('Rolig · Én ting ad gangen','Rolig · One thing at a time');
document.getElementById('app').innerHTML=header('rolig','sun',`<a href="#guide">${t('Øv en situation','Practise a situation')}</a><a href="#sources">${t('Kilder','Sources')}</a>`)+`<main class="page rolig-page" id="main"><div class="notice exercise row">${icon('book')}<span>${t('ØVELSE · Ingen aktuel hændelse. Ingen livevarsler.','PRACTICE · No current incident. No live alerts.')}</span></div><section class="rolig-hero"><div><div class="eyebrow">${t('Din guide til at øve beredskab','Your guide to practising preparedness')}</div><h1>${t('Én ting<br>ad gangen.','One thing<br>at a time.')}</h1><p class="lead">${t('Når noget uventet sker, hjælper en enkel plan. Lær de vigtigste skridt i ro og mag.','When the unexpected happens, a simple plan helps. Learn the essential steps at your own pace.')}</p></div><div class="orbit" aria-hidden="true">${icon('sun')}<i></i></div></section><div class="scenario-tabs" role="group" aria-label="${t('Vælg øvelse','Choose an exercise')}">${Object.entries(scenarios).map(([key,x])=>`<button class="scenario-tab ${state.scenario===key?'active':''}" aria-pressed="${state.scenario===key}" onclick="selectScenario('${key}')">${icon(x.icon,'big')}<span><strong>${t(...x.title)}</strong><small>${t(...x.sub)}</small></span></button>`).join('')}</div><section class="guide-layout" id="guide"><aside><div class="eyebrow" style="margin-top:10px">${t('Din øvelse','Your practice')}</div><div class="guide-index">${s.steps.map((x,i)=>`<button class="${i===state.step?'active':''}" onclick="goStep(${i})" ${i===state.step?'aria-current="step"':''}><span>${i+1}</span><b>${t(...x.title)}</b></button>`).join('')}</div><div class="subtle muted" style="padding:15px 8px">${t('Din fremdrift gemmes på denne enhed.','Your progress is saved on this device.')}</div></aside><article class="card guide-step"><div class="row between step-top"><span class="badge">${t('Trin','Step')} ${state.step+1} / 3</span><span class="subtle muted">${checked.length}/${step.tasks.length} ${t('gennemgået','reviewed')}</span></div><h2 tabindex="-1" id="step-title">${t(...step.title)}</h2><p class="description">${t(...step.desc)}</p><div>${step.tasks.map((x,i)=>`<label class="check-row"><input type="checkbox" data-step-task="${i}" ${checked.includes(i)?'checked':''}><span><strong>${t(...x)}</strong></span></label>`).join('')}</div><div class="notice">${t(...step.note)}</div><div class="bar" aria-label="${t('Øvelsens trin','Exercise steps')}"><span style="width:${(state.step+1)/3*100}%"></span></div><div class="row between guide-buttons"><button class="btn quiet" onclick="goStep(${state.step-1})" ${state.step===0?'disabled':''}>← ${t('Tilbage','Back')}</button>${state.step<2?`<button class="btn primary" onclick="goStep(${state.step+1})">${t('Næste trin','Next step')}${icon('arrow')}</button>`:`<button class="btn primary" onclick="finishPractice()">${icon('check')}${t('Afslut øvelse','Finish practice')}</button>`}</div></article></section><div class="trusted"><a href="https://www.dr.dk/" target="_blank" rel="noopener">DR ↗<small>${t('Nyheder og beredskabsmeddelelser','News and emergency messages')}</small></a><a href="https://www.tv2.dk/" target="_blank" rel="noopener">TV 2 ↗<small>${t('Nyheder og information','News and information')}</small></a><a href="https://politi.dk/" target="_blank" rel="noopener">Politi ↗<small>${t('Information fra politiet','Police information')}</small></a></div><div class="row between wrap rolig-bottom"><span class="muted">${t('Kend rådene, før du får brug for dem.','Know the guidance before you need it.')}</span><button class="btn quiet" onclick="offlineDownload()">${icon('download')}${t('Hent guide til offlinebrug','Download guide for offline use')}</button></div>${sources()}</main>`+footer();
document.querySelectorAll('[data-step-task]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.stepTask);state.done[id]=el.checked?[...new Set([...checked,i])]:checked.filter(x=>x!==i);persist();document.querySelector(`[data-step-task="${i}"]`)?.focus();});
}
function persist(){save(KEY,state);updatePage();}
function selectScenario(key){state.scenario=key;state.step=0;persist();}
function goStep(i){state.step=Math.min(2,Math.max(0,i));persist();document.getElementById('step-title')?.focus({preventScroll:true});}
function finishPractice(){const s=scenarios[state.scenario],complete=s.steps.every((step,i)=>(state.done[state.scenario+'-'+i]||[]).length===step.tasks.length);toast(complete?t('Øvelsen er gennemgået. Genbesøg den gerne senere.','Practice reviewed. You can revisit it any time.'):t('Du har stadig punkter at gennemgå i øvelsen.','You still have items to review in this exercise.'));}
'''
write_app('03-rolig.html','Rolig · Én ting ad gangen',ROLIG_CSS,ROLIG_JS)

SAMMEN_CSS=r'''
:root{--bg:#f3f6fa;--card:#fff;--ink:#223854;--accent:#3c65bb;--muted:#708096;--line:#dce4ef;--soft:#eaf0fc}.sammen-hero{display:grid;grid-template-columns:1fr 330px;gap:40px;align-items:center;margin:12px 0 35px}.sammen-hero h1{font-size:clamp(37px,4.5vw,56px);max-width:650px}.network-art{width:100%;max-height:230px}.plan-tabs{display:flex;border-bottom:1px solid var(--line);gap:25px;margin-bottom:28px}.plan-tabs a{text-decoration:none;font-size:13px;font-weight:650;padding:15px 2px}.plan-tabs a:first-child{border-bottom:2px solid var(--accent);color:var(--accent)}.sammen-layout{display:grid;grid-template-columns:1.65fr 1fr;gap:24px}.person{display:flex;align-items:center;gap:14px;padding:21px 0;border-bottom:1px solid var(--line)}.person:last-child{border:0}.avatar{width:45px;height:45px;flex-shrink:0;border-radius:50%;display:grid;place-items:center;background:#e9eef7;color:#466390;font-weight:650;font-size:14px}.person:nth-child(2) .avatar{background:#f6e9e2;color:#a9785d}.person:nth-child(3) .avatar{background:#e9efe0;color:#6e8055}.person-info{flex:1}.person-info strong{font-size:14px}.person-info p{font-size:11px}.role-pill{background:#f3f6fa;color:#708096;font-size:10px;padding:5px 9px;border-radius:6px}.person-actions{display:flex;gap:5px}.person-actions .square{width:33px;height:33px;min-width:33px}.person-actions .icon{width:16px}.meeting{background:#e8effb}.meeting .pin-icon{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:#d3e0f8;color:var(--accent);margin-bottom:18px}.meeting p{font-size:12px;margin-top:12px}.meeting h3{font-size:21px}.meeting .btn{margin-top:20px}.task-owner{font-size:11px;color:var(--accent);font-weight:600}.task-card{padding-bottom:12px}.print-card{border-style:dashed}.print-card p{font-size:12px;margin:10px 0 18px}.privacy-line{font-size:11px;margin:17px 0 25px}.print-title{display:none}.sammen-layout .card h2{font-size:23px}.role-select{border:1px solid var(--line);background:var(--bg);border-radius:5px;padding:5px;max-width:115px;color:var(--ink);font-size:11px}
@media(max-width:850px){.sammen-layout{grid-template-columns:1fr}.sammen-hero{grid-template-columns:1fr 220px;gap:15px}}
@media(max-width:600px){.sammen-hero{grid-template-columns:1fr}.network-art{max-height:175px}.person{gap:10px;flex-wrap:wrap}.person-actions{margin-left:auto}.role-pill{font-size:9px}.person-info{min-width:120px}.plan-tabs{gap:18px}.sammen-hero h1{font-size:38px}}
@media print{.sammen-hero,.network-art,.plan-tabs,.task-card,.people-card,.meeting,.privacy-line{display:none!important}.sammen-layout{display:block}.print-card .print-details{display:block!important}.print-card{border:2px solid #aaa!important;max-width:700px}.print-card h2{font-size:30px}.print-card strong{color:#17263c}.print-card p{color:#444}.print-card .print-details div{padding:10px 0}.print-title{margin-bottom:20px}}
'''

SAMMEN_JS=r'''
const KEY='prepared-sammen-v1';
const defaults=()=>({people:[{id:'p1',name:'Maja',role:'family',phone:''},{id:'p2',name:'Jonas',role:'family',phone:''},{id:'p3',name:'Anna',role:'neighbour',phone:''}],meeting:'',backup:'',checked:[],owners:{water:'p1',radio:'p2',neighbour:'p3',transport:'p2'}});
let state=read(KEY,defaults());if(!state||!Array.isArray(state.people))state=defaults();
const tasks=[['water','Vand og mad til tre døgn','Food and water for three days'],['radio','FM-radio og opladning','FM radio and charging'],['neighbour','Aftal et nabotjek','Arrange a neighbour check-in'],['transport','Aftal hjælp til transport','Arrange transport help']];
const roleName=r=>r==='neighbour'?t('Nabo','Neighbour'):r==='friend'?t('Ven','Friend'):t('Familie','Family');
function render(){const complete=tasks.filter(x=>state.checked.includes(x[0])).length;
const art=`<svg viewBox="0 0 360 240" class="network-art" aria-hidden="true"><ellipse cx="180" cy="128" rx="139" ry="96" fill="#e8eef8"/><path d="m80 80 100 62 108-60M180 142l-1 67" stroke="#b4c5e2" stroke-width="2" stroke-dasharray="6 7"/><circle cx="80" cy="79" r="30" fill="#cedbef"/><circle cx="289" cy="80" r="31" fill="#e2cfbf"/><circle cx="180" cy="205" r="27" fill="#d2dfc8"/><circle cx="80" cy="70" r="9" fill="#7195c5"/><path d="M63 96a17 17 0 0 1 34 0" fill="#7195c5"/><circle cx="289" cy="71" r="9" fill="#ad8d74"/><path d="M272 97a17 17 0 0 1 34 0" fill="#ad8d74"/><circle cx="180" cy="198" r="8" fill="#8da47c"/><path d="M166 220a14 14 0 0 1 28 0" fill="#8da47c"/><rect x="141" y="105" width="78" height="70" rx="15" fill="#3c65bb"/><path d="m158 133 22-18 22 18v26h-44Z" stroke="#fff" stroke-width="2" fill="none"/><path d="M175 158v-17h12v17" stroke="#fff" stroke-width="2" fill="none"/><circle cx="239" cy="181" r="15" fill="#fff"/><path d="m232 181 5 5 10-11" stroke="#86a06f" stroke-width="2" fill="none"/></svg>`;
document.title=t('Sammen · En fælles plan','Sammen · A shared plan');
document.getElementById('app').innerHTML=header('sammen','people',`<a href="#people">${t('Mine nærmeste','My circle')}</a><a href="#plan">${t('Vores plan','Our plan')}</a>`)+`<main class="page" id="main"><div class="print-title"><h1>${t('Vores beredskabskort','Our emergency card')}</h1></div><section class="sammen-hero"><div><div class="eyebrow">${t('Forbered jer sammen','Prepare together')}</div><h1>${t('Vi er bedre<br>forberedt sammen.','Better prepared.<br>Together.')}</h1><p class="lead">${t('En plan for dig og dem, du holder af. Fordel opgaverne, aftal et mødested, og få de vigtige numre på papir.','A plan for you and those you care about. Share tasks, agree a meeting point and put important numbers on paper.')}</p><p class="privacy-line muted">${t('Eksempelnavne · Lokal plan på denne enhed · Ingen invitationer eller beskeder sendes.','Example names · Local plan on this device · No invitations or messages are sent.')}</p></div>${art}</section><nav class="plan-tabs" aria-label="${t('Planens sektioner','Plan sections')}"><a href="#plan">${t('Vores overblik','Our overview')}</a><a href="#people">${t('Vores personer','Our people')}</a><a href="#emergency-card">${t('Beredskabskort','Emergency card')}</a></nav><div class="sammen-layout" id="plan"><div class="stack"><section class="card people-card" id="people"><div class="row between section-head"><h2>${t('Dine nærmeste','Your circle')}</h2><button class="btn quiet" onclick="openPerson()">${icon('plus')}${t('Tilføj','Add')}</button></div>${state.people.length?state.people.map(p=>`<div class="person"><span class="avatar">${esc(p.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</span><div class="person-info"><strong>${esc(p.name)}</strong><p>${p.phone?esc(p.phone):t('Tilføj telefonnummer','Add a phone number')}</p></div><span class="role-pill">${roleName(p.role)}</span><div class="person-actions"><button class="square" onclick="openPerson('${p.id}')" aria-label="${t('Redigér','Edit')} ${esc(p.name)}">${icon('edit')}</button><button class="square" onclick="deletePerson('${p.id}')" aria-label="${t('Fjern','Remove')} ${esc(p.name)}">${icon('close')}</button></div></div>`).join(''):`<div class="empty">${t('Tilføj din første person.','Add your first person.')}</div>`}</section><section class="card task-card"><div class="row between section-head"><h2>${t('Hvem tager sig af hvad?','Who takes care of what?')}</h2><span class="badge">${complete}/4</span></div><div class="bar"><span style="width:${complete/4*100}%"></span></div>${tasks.map(x=>`<div class="row between" style="gap:10px;border-bottom:1px solid var(--line)"><label class="check-row" style="border:0;flex:1"><input data-shared-task="${x[0]}" type="checkbox" ${state.checked.includes(x[0])?'checked':''}><span><strong>${t(x[1],x[2])}</strong></span></label><label><span class="sr-only">${t('Ansvarlig for','Responsible for')} ${t(x[1],x[2])}</span><select class="role-select" onchange="state.owners['${x[0]}']=this.value;persist()"><option value="">${t('Vælg person','Choose person')}</option>${state.people.map(p=>`<option value="${p.id}" ${state.owners[x[0]]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>`).join('')}<p class="subtle muted" style="margin-top:18px">${t('Markér, når I har lavet en aftale. Dette er ikke fælles synkronisering.','Check an item when you have agreed on it. This plan does not sync between people.')}</p></section></div><aside class="stack" style="align-content:start"><section class="card meeting"><span class="pin-icon">${icon('pin')}</span><div class="eyebrow">${t('Hvis forbindelsen ryger','If connections fail')}</div><h3>${state.meeting?esc(state.meeting):t('Hvor mødes I?','Where will you meet?')}</h3><p>${state.backup?t('Alternativ: ','Backup: ')+esc(state.backup):t('Aftal et sted på forhånd. Vælg også et alternativ, hvis området ikke er sikkert.','Agree a place in advance. Choose a backup if the area is unsafe.')}</p><button class="btn" onclick="openMeeting()">${icon('edit')}${state.meeting?t('Redigér aftale','Edit plan'):t('Aftal mødested','Set meeting point')}</button></section><section class="card print-card" id="emergency-card"><h2>${t('En plan på papir.','A plan on paper.')}</h2><p>${t('Telefonen kan løbe tør. Print jeres aftaler og vigtige numre, og læg kortet et sted, alle kender.','Your phone may run out of power. Print your plans and important numbers and keep the card where everyone can find it.')}</p><div class="print-details" style="display:none"><div><strong>${t('Mødested','Meeting point')}</strong><p>${esc(state.meeting||t('Ikke aftalt','Not set'))}</p><p>${t('Alternativ: ','Backup: ')}${esc(state.backup||'—')}</p></div>${state.people.map(p=>`<div><strong>${esc(p.name)} · ${roleName(p.role)}</strong><p>${esc(p.phone||t('Intet nummer tilføjet','No number added'))}</p></div>`).join('')}<div><strong>${t('Aftaler','Plans')}</strong>${tasks.map(x=>`<p>${t(x[1],x[2])}: ${esc(state.people.find(p=>p.id===state.owners[x[0]])?.name||t('Ikke fordelt','Unassigned'))}</p>`).join('')}</div><div><strong>1-1-2</strong><p>${t('Kun ved akut behov for ambulance, politi eller brandvæsen.','Only for emergencies requiring ambulance, police or fire services.')}</p></div></div><button class="btn primary" onclick="window.print()">${icon('print')}${t('Print beredskabskort','Print emergency card')}</button></section><div class="notice">${t('Har nogen særlige behov? Tal om medicin, børn, kæledyr og hjælp til transport.','Does anyone have special needs? Discuss medicine, children, pets and transport help.')}</div></aside></div>${sources()}</main>`+footer()+`<dialog id="person-dialog"><form id="person-form"><div class="row between"><h2 id="person-title"></h2><button class="square" type="button" onclick="document.getElementById('person-dialog').close()" aria-label="${t('Luk','Close')}">${icon('close')}</button></div><input id="person-id" type="hidden"><label class="field">${t('Navn','Name')}<input id="person-name" maxlength="60" required></label><label class="field">${t('Relation','Relationship')}<select id="person-role"><option value="family">${t('Familie','Family')}</option><option value="neighbour">${t('Nabo','Neighbour')}</option><option value="friend">${t('Ven','Friend')}</option></select></label><label class="field">${t('Telefonnummer (valgfrit)','Phone number (optional)')}<input id="person-phone" type="tel" maxlength="30" autocomplete="off"></label><p class="subtle">${t('Oplysninger gemmes kun i denne browser. Brug en enhed, du har tillid til.','Details are saved only in this browser. Use a device you trust.')}</p><button class="btn primary" type="submit">${t('Gem person','Save person')}</button></form></dialog><dialog id="meeting-dialog"><form id="meeting-form"><div class="row between"><h2>${t('Jeres mødesteder','Your meeting points')}</h2><button class="square" type="button" onclick="document.getElementById('meeting-dialog').close()" aria-label="${t('Luk','Close')}">${icon('close')}</button></div><label class="field">${t('Primært mødested','Primary meeting point')}<input id="meeting-name" required maxlength="120" placeholder="${t('Fx ved hovedindgangen til biblioteket','E.g. the main library entrance')}"></label><label class="field">${t('Alternativt sted (valgfrit)','Backup location (optional)')}<input id="meeting-backup" maxlength="120"></label><p class="subtle">${t('Vælg kun et mødested, hvis det er sikkert at komme dertil. Følg aktuelle anvisninger.','Only use a meeting point if it is safe to get there. Follow current instructions.')}</p><button class="btn primary" type="submit">${t('Gem aftale','Save plan')}</button></form></dialog>`;
document.getElementById('person-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('person-name').value.trim();if(!name)return;const id=document.getElementById('person-id').value;const person={id:id||'p'+Date.now(),name,role:document.getElementById('person-role').value,phone:document.getElementById('person-phone').value.trim()};state.people=id?state.people.map(p=>p.id===id?person:p):[...state.people,person];persist();toast(t('Personen er gemt på denne enhed','Person saved on this device'));};
document.getElementById('meeting-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('meeting-name').value.trim();if(!name)return;state.meeting=name;state.backup=document.getElementById('meeting-backup').value.trim();persist();toast(t('Jeres aftale er gemt','Your plan is saved'));};
document.querySelectorAll('[data-shared-task]').forEach(el=>el.onchange=()=>{const id=el.dataset.sharedTask;state.checked=el.checked?[...new Set([...state.checked,id])]:state.checked.filter(x=>x!==id);persist();document.querySelector(`[data-shared-task="${id}"]`)?.focus();});
}
function persist(){save(KEY,state);updatePage();}
function openPerson(id=''){const p=state.people.find(p=>p.id===id);document.getElementById('person-title').textContent=p?t('Redigér person','Edit person'):t('Tilføj en person','Add a person');document.getElementById('person-id').value=id;document.getElementById('person-name').value=p?.name||'';document.getElementById('person-role').value=p?.role||'family';document.getElementById('person-phone').value=p?.phone||'';document.getElementById('person-dialog').showModal();}
function deletePerson(id){state.people=state.people.filter(p=>p.id!==id);for(const k of Object.keys(state.owners))if(state.owners[k]===id)state.owners[k]='';persist();toast(t('Personen er fjernet fra planen','Person removed from the plan'));}
function openMeeting(){document.getElementById('meeting-name').value=state.meeting;document.getElementById('meeting-backup').value=state.backup;document.getElementById('meeting-dialog').showModal();}
'''
write_app('04-sammen.html','Sammen · En fælles beredskabsplan',SAMMEN_CSS,SAMMEN_JS)

PARAT_CSS=r'''
:root{--bg:#f9f7f4;--ink:#292a38;--accent:#a94327;--muted:#777581;--line:#e6e1dc;--soft:#f4e6de;--card:#fff}.parat-hero{display:grid;grid-template-columns:1.3fr 1fr;gap:50px;align-items:center;padding:15px 0 40px}.parat-hero h1{font-size:clamp(38px,5vw,61px);max-width:620px}.parat-hero em{font-style:normal;color:var(--accent)}.journey-art{width:100%;max-height:290px}.journey-layout{display:grid;grid-template-columns:1.5fr 1fr;gap:26px}.lesson{display:flex;align-items:center;gap:19px;padding:20px 0;border-bottom:1px solid var(--line)}.lesson:last-child{border-bottom:0}.lesson-num{width:48px;height:48px;border-radius:14px;background:#f2e8dc;display:grid;place-items:center;color:#ac7b4c;flex-shrink:0}.lesson:nth-child(2) .lesson-num{background:#dfe9ec;color:#5f8694}.lesson:nth-child(3) .lesson-num{background:#eee5f3;color:#9272a6}.lesson:nth-child(4) .lesson-num{background:#e5ebdc;color:#7b8a5d}.lesson:nth-child(5) .lesson-num{background:#f3e1d9;color:#bd7b61}.lesson-info{flex:1}.lesson-info h3{font-size:15px}.lesson-info p{font-size:11px;margin-top:5px}.lesson .btn{min-width:75px;padding:8px 12px;font-size:11px}.lesson .done-dot{color:var(--accent);width:32px}.quiz-card{background:#eee8f5;border-color:#e1d8ec}.quiz-card .eyebrow{color:#79648a}.quiz-card h2{font-size:27px}.quiz-card p{font-size:13px;line-height:1.7;margin:15px 0 20px;color:#6b6175}.quiz-card .btn{background:#75618c;border-color:#75618c;color:white}.quiz-illustration{height:115px;display:flex;align-items:center;justify-content:center;margin:5px 0 25px}.quiz-circle{width:98px;height:98px;display:grid;place-items:center;background:#dcd0e9;border-radius:50%;color:#75618c;font-size:55px;transform:rotate(-8deg);font-weight:600}.mini-progress{padding:24px;background:#fff;border-radius:17px;border:1px solid var(--line);margin-top:22px}.days{display:flex;gap:8px;margin:20px 0 15px}.day{height:33px;flex:1;display:grid;place-items:center;border-radius:7px;background:#f1eeeb;color:var(--muted);font-size:11px}.day.done{background:var(--accent);color:#fff}.reflection p{font-size:12px;margin-top:12px}.quiz-modal .option{display:flex;gap:12px;align-items:center;width:100%;text-align:left;border:1px solid var(--line);border-radius:10px;padding:14px;background:var(--card);margin-top:10px;font-size:13px}.quiz-modal .option:disabled{opacity:1;cursor:default}.quiz-modal .option.chosen{border-color:var(--accent);background:var(--soft)}.quiz-modal .option.correct{background:#e7f0df;border-color:#849b68;color:#34522f}.quiz-modal .option.wrong{background:#fae4dc;border-color:#b86f58;color:#7e3427}.quiz-feedback{font-size:13px;margin:18px 0;padding:15px;border-radius:10px;background:var(--soft)}.lesson-modal .lesson-content{font-size:16px;line-height:1.8;margin:20px 0}.lesson-modal .notice{margin-bottom:20px}.lesson-modal .eyebrow{margin:15px 0}.quiz-modal h3{font-size:22px}.quiz-score{font-size:56px;color:#75618c;text-align:center;margin:15px}.quiz-modal .modal-head{margin-bottom:20px}
@media(max-width:850px){.parat-hero{gap:25px}.journey-layout{grid-template-columns:1.3fr 1fr}.lesson{gap:12px}.lesson-num{width:38px;height:42px}.lesson-info h3{font-size:13px}.lesson .btn{min-width:65px}}
@media(max-width:650px){.parat-hero{grid-template-columns:1fr}.journey-art{max-height:210px}.journey-layout{grid-template-columns:1fr}.lesson{gap:12px}.lesson-info h3{font-size:14px}.lesson-info p{font-size:10px}.parat-hero h1{font-size:42px}.lesson-num{width:36px}.lesson .btn{padding:8px}.done-dot{display:none}}
'''

PARAT_JS=r'''
const KEY='prepared-parat-v1';
let state=read(KEY,{complete:[],best:null});if(!state||!Array.isArray(state.complete))state={complete:[],best:null};
let lessonIndex=0,questionIndex=0,answers=[],revealed=false;
const lessons=[
{icon:'drop',title:['Start med vand','Start with water'],time:['2 minutter','2 minutes'],desc:['Beregn dit behov, og find et sted til vandet.','Calculate your needs and choose a place for water.'],body:['Tre liter pr. person pr. døgn er udgangspunktet. Det bliver ni liter pr. person til tre døgn. Husk ekstra vand til husdyr.','Start with three litres per person per day. That is nine litres per person for three days. Remember extra water for pets.'],action:['Din opgave: Regn husstandens behov ud. Vælg et mørkt og køligt sted til vandet.','Your task: Calculate your household’s needs. Choose a cool, dark place to store water.']},
{icon:'box',title:['Mad, I faktisk spiser','Food you actually eat'],time:['3 minutter','3 minutes'],desc:['Byg dit lager op med kendte hverdagsvarer.','Build supplies using familiar everyday food.'],body:['Vælg holdbare varer, der kan klare sig uden køl, gerne uden tilberedning. Brug af lageret i hverdagen, og fyld op igen.','Choose long-life food that needs no refrigeration, preferably ready to eat. Use supplies in everyday life and replenish them.'],action:['Din opgave: Find tre varer, din husstand kan lide, som ikke kræver strøm for at blive spist.','Your task: Find three foods your household enjoys that do not need electricity to eat.']},
{icon:'bolt',title:['Lys og forbindelse','Light and connection'],time:['2 minutter','2 minutes'],desc:['Find de små ting, der gør en forskel.','Find the small things that make a difference.'],body:['En lommelygte og en opladet powerbank hjælper ved strømsvigt. En FM-radio på batteri, håndsving eller solceller kan give information, når nettet svigter.','A torch and a charged power bank help during an outage. A battery, hand-crank or solar-powered FM radio can provide information when networks fail.'],action:['Din opgave: Find din lommelygte, tjek batterierne, og find ud af, hvor du kan høre FM-radio.','Your task: Find your torch, check its batteries and work out how to listen to FM radio.']},
{icon:'people',title:['Lav en lille aftale','Make a small plan'],time:['3 minutter','3 minutes'],desc:['Tal med dem, du vil passe på.','Talk to the people you care about.'],body:['Tal om særlige behov, transport og hjælp til hinanden. Skriv vigtige telefonnumre på papir, så I kan finde dem uden en opladet telefon.','Discuss special needs, transport and helping each other. Write important phone numbers on paper so you can find them without a charged phone.'],action:['Din opgave: Skriv to vigtige numre ned, og aftal, hvem I kontakter ved problemer.','Your task: Write down two important numbers and agree who to contact if problems arise.']},
{icon:'radio',title:['Kend varslingen','Know the warning'],time:['2 minutter','2 minutes'],desc:['Lær, hvad du gør, når en sirene lyder.','Learn what to do when a siren sounds.'],body:['Ved en fysisk varslingssirene: Gå indenfor og søg information hos DR eller TV 2. Ved S!RENEN på mobilen: Stop, læs hele meddelelsen og følg dens anvisninger.','For a physical warning siren: Go indoors and seek information from DR or TV 2. For S!RENEN on your phone: Stop, read the full message and follow its instructions.'],action:['Din opgave: Fortæl en anden i husstanden, hvad rådene betyder.','Your task: Explain the guidance to someone in your household.']}
];
const questions=[
{q:['Hvor meget drikkevand er udgangspunktet for én person til tre døgn?','How much drinking water is recommended for one person for three days?'],options:[['3 liter','3 litres'],['6 liter','6 litres'],['9 liter','9 litres']],correct:2,why:['3 liter pr. person pr. døgn × 3 døgn = 9 liter.','3 litres per person per day × 3 days = 9 litres.']},
{q:['Du hører en fysisk varslingssirene. Hvad gør du?','You hear a physical warning siren. What do you do?'],options:[['Går indenfor og søger information hos DR eller TV 2','Go indoors and get information from DR or TV 2'],['Går ud for at se, hvad der er sket','Go outside to see what has happened'],['Ringer 1-1-2 for at spørge','Call 1-1-2 to ask about it']],correct:0,why:['Gå indenfor og søg information. 1-1-2 er til akutte nødsituationer.','Go indoors and seek information. 1-1-2 is for emergencies.']},
{q:['Hvor må du bruge en grill til madlavning ved strømsvigt?','Where may you use a grill for cooking during an outage?'],options:[['I køkkenet med et åbent vindue','In the kitchen with an open window'],['Udendørs, ikke i helt eller delvist lukkede rum','Outdoors, not in fully or partially enclosed spaces'],['I en lukket garage','In a closed garage']],correct:1,why:['Grill og lignende må aldrig bruges indendørs eller i helt eller delvist lukkede rum på grund af kuliltefare.','Never use grills indoors or in fully or partially enclosed spaces because of carbon monoxide risk.']},
{q:['Hvilket madlager giver bedst mening?','Which food supplies make most sense?'],options:[['Kun varer, der kræver fryser','Only food that needs a freezer'],['Tilfældige varer, som ingen kan lide','Random food that nobody likes'],['Holdbar mad, I kan lide og løbende bruger','Long-life food you enjoy and regularly use']],correct:2,why:['Brug og genopfyld lageret. Det gør forberedelse til en del af hverdagen.','Use and replenish supplies. That makes preparedness part of everyday life.']},
{q:['Hvad er en god plan, hvis internettet svigter?','What is a good plan if the internet fails?'],options:[['Kun at have numre i en cloud-konto','Keep numbers only in a cloud account'],['Have numre på papir og adgang til FM-radio','Have numbers on paper and access to FM radio'],['Dele ubekræftede opslag hurtigst muligt','Share unverified posts as quickly as possible']],correct:1,why:['Vigtige numre på papir og FM-radio hjælper, hvis digitale kanaler svigter.','Important numbers on paper and FM radio help when digital channels fail.']}
];
function render(){const count=state.complete.length;document.title=t('Parat · Små skridt, større ro','Parat · Small steps, more confidence');
const art=`<svg viewBox="0 0 400 300" class="journey-art" aria-hidden="true"><circle cx="209" cy="151" r="125" fill="#f0e9df"/><path d="M70 241c10-55 98-9 100-61s-38-39-24-76 99 13 116-28" stroke="#d3c3b2" stroke-width="3" stroke-dasharray="5 8" fill="none"/><rect x="66" y="181" width="72" height="79" rx="17" fill="#d8e4e7" transform="rotate(-9 66 181)"/><path d="M96 197s-14 18-14 26a15 15 0 0 0 30 0c0-8-16-26-16-26" fill="#83a1ac"/><rect x="148" y="109" width="92" height="91" rx="22" fill="#ded0e9" transform="rotate(8 148 109)"/><path d="m172 150 16 15 30-30" stroke="#9272a6" stroke-width="8" stroke-linecap="round" stroke-linejoin="round" fill="none"/><rect x="247" y="42" width="74" height="79" rx="18" fill="#b95335" transform="rotate(-9 247 42)"/><path d="m268 81 11 11 23-26" stroke="#fff1de" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" fill="none"/><path d="m301 180 5 13 13 5-13 5-5 13-5-13-13-5 13-5Z" fill="#ccad79"/><circle cx="95" cy="102" r="8" fill="#d6c6b7"/><path d="m332 54 5-13m6 22 12-3" stroke="#d2b69d" stroke-width="3" stroke-linecap="round"/></svg>`;
document.getElementById('app').innerHTML=header('parat','spark',`<a href="#lessons">${t('Min startplan','My starter plan')}</a><a href="#quiz-card">${t('Test din viden','Test your knowledge')}</a>`)+`<main class="page" id="main"><section class="parat-hero"><div><div class="eyebrow">${t('Lidt i dag gør en forskel','A little today makes a difference')}</div><h1>${t('Fem minutter i dag.<br><em>Mere ro i morgen.</em>','Five minutes today.<br><em>More calm tomorrow.</em>')}</h1><p class="lead">${t('Beredskab behøver ikke være et stort projekt. Start med én lille opgave, og byg videre derfra.','Preparedness does not need to be a big project. Start with one small task and build from there.')}</p><a class="btn primary" style="margin-top:25px" href="#lessons">${t('Tag det første skridt','Take the first step')}${icon('arrow')}</a></div>${art}</section><div class="journey-layout"><section class="card" id="lessons"><div class="row between section-head"><div><div class="eyebrow" style="margin-bottom:8px">${t('Din startplan','Your starter plan')}</div><h2>${t('Fem små skridt til tre døgn.','Five small steps for three days.')}</h2></div></div>${lessons.map((x,i)=>`<article class="lesson"><div class="lesson-num">${icon(x.icon)}</div><div class="lesson-info"><h3>${t(...x.title)}</h3><p>${t(...x.time)} · ${t(...x.desc)}</p></div>${state.complete.includes(i)?`<span class="done-dot">${icon('check')}</span>`:''}<button class="btn ${state.complete.includes(i)?'':'primary'}" onclick="openLesson(${i})">${state.complete.includes(i)?t('Se igen','Revisit'):t('Start','Start')}</button></article>`).join('')}<p class="subtle muted" style="margin-top:18px">${t('En startplan, ikke en komplet beredskabstjekliste. Se de samlede myndighedsråd nedenfor.','A starter plan, not a complete preparedness checklist. See the full official guidance below.')}</p></section><aside class="stack" style="align-content:start"><section class="card quiz-card" id="quiz-card"><div class="eyebrow">${t('En lille videntest','A little knowledge check')}</div><div class="quiz-illustration" aria-hidden="true"><div class="quiz-circle">?</div></div><h2>${t('Hvad ved du allerede?','What do you already know?')}</h2><p>${t('Fem spørgsmål fra hverdagen. Lær noget nyt undervejs — uden tidspres.','Five everyday questions. Learn something along the way — with no time pressure.')}</p><button class="btn" onclick="startQuiz()">${t('Tag testen','Take the quiz')}${icon('arrow')}</button>${state.best!==null?`<p class="subtle">${t('Dit bedste resultat','Your best score')}: ${state.best}/5</p>`:''}</section><section class="mini-progress"><div class="row between"><h3>${t('Din fremdrift','Your progress')}</h3><span class="badge">${count}/5</span></div><div class="days">${lessons.map((x,i)=>`<span class="day ${state.complete.includes(i)?'done':''}" aria-label="${t(...x.title)}${state.complete.includes(i)?t(' gennemført',' completed'):''}">${state.complete.includes(i)?'✓':i+1}</span>`).join('')}</div><p class="subtle">${count===5?t('Alle fem skridt er gennemgået. Gennemgå også de fulde råd.','All five steps reviewed. Read the full guidance too.'):t('Tag dem i dit eget tempo. Vi gemmer dine fremskridt i denne browser.','Go at your own pace. We save your progress in this browser.')}</p></section></aside></div>${sources()}</main>`+footer()+`<dialog id="lesson-dialog" class="lesson-modal"></dialog><dialog id="quiz-dialog" class="quiz-modal"></dialog>`;
}
function openLesson(i){lessonIndex=i;const x=lessons[i],el=document.getElementById('lesson-dialog');el.innerHTML=`<div class="row between"><span class="badge">${t('Skridt','Step')} ${i+1}/5</span><button class="square" aria-label="${t('Luk','Close')}" onclick="document.getElementById('lesson-dialog').close()">${icon('close')}</button></div><div class="eyebrow">${t(...x.time)}</div><h2>${t(...x.title)}</h2><p class="lesson-content">${t(...x.body)}</p><div class="notice">${t(...x.action)}</div><button class="btn primary" onclick="completeLesson()">${icon('check')}${t('Jeg har gjort det','I have done this')}</button>`;el.showModal();}
function completeLesson(){state.complete=[...new Set([...state.complete,lessonIndex])];save(KEY,state);updatePage();toast(t('Et lille skridt mere. Godt gået.','One more small step. Well done.'));}
function startQuiz(){questionIndex=0;answers=[];revealed=false;renderQuiz();document.getElementById('quiz-dialog').showModal();}
function renderQuiz(){const el=document.getElementById('quiz-dialog');if(questionIndex>=questions.length){const score=answers.filter((x,i)=>x===questions[i].correct).length;state.best=Math.max(state.best||0,score);save(KEY,state);el.innerHTML=`<div class="eyebrow">${t('Du er i mål','You have finished')}</div><h2>${t('Lidt klogere. Lidt mere parat.','A little wiser. A little more prepared.')}</h2><div class="quiz-score">${score}/5</div><p>${t('Viden er en start. Brug din startplan til at gøre den konkret.','Knowledge is a start. Use your starter plan to put it into practice.')}</p><button class="btn primary" style="margin-top:25px" onclick="document.getElementById('quiz-dialog').close();updatePage()">${t('Tilbage til min plan','Back to my plan')}</button>`;return;}
const q=questions[questionIndex],choice=answers[questionIndex];el.innerHTML=`<div class="row between modal-head"><span class="badge">${t('Spørgsmål','Question')} ${questionIndex+1}/5</span><button class="square" aria-label="${t('Luk','Close')}" onclick="document.getElementById('quiz-dialog').close()">${icon('close')}</button></div><h3 tabindex="-1" id="question-title">${t(...q.q)}</h3><div>${q.options.map((x,i)=>`<button class="option ${revealed?(i===q.correct?'correct':i===choice?'wrong':''):choice===i?'chosen':''}" onclick="chooseAnswer(${i})" ${revealed?'disabled':''} aria-pressed="${choice===i}"><strong>${String.fromCharCode(65+i)}</strong><span>${t(...x)}</span></button>`).join('')}</div>${revealed?`<div class="quiz-feedback" role="status"><strong>${choice===q.correct?t('Korrekt. ','Correct. '):t('Det rigtige svar er markeret. ','The correct answer is highlighted. ')}</strong>${t(...q.why)}</div><button class="btn primary" style="margin-top:15px" onclick="nextQuestion()">${questionIndex===4?t('Se resultat','See results'):t('Næste spørgsmål','Next question')}${icon('arrow')}</button>`:`<button class="btn primary" style="margin-top:22px" onclick="revealAnswer()" ${choice===undefined?'disabled':''}>${t('Tjek mit svar','Check my answer')}</button>`}`;
}
function chooseAnswer(i){if(revealed)return;answers[questionIndex]=i;renderQuiz();}
function revealAnswer(){if(answers[questionIndex]===undefined)return;revealed=true;renderQuiz();}
function nextQuestion(){questionIndex++;revealed=false;renderQuiz();document.getElementById('question-title')?.focus();}
'''
write_app('05-parat.html','Parat · Små skridt til et beredskab',PARAT_CSS,PARAT_JS)

GALLERY_CSS=r'''
:root{--bg:#f7f6f3;--card:#fff;--ink:#202b3b;--accent:#a94327;--soft:#f2e7df;--line:#e2e1dd;--muted:#777d86}.gallery-hero{padding:20px 0 44px;max-width:850px}.gallery-hero h1{font-size:clamp(42px,5.6vw,70px)}.gallery-hero h1 span{color:var(--accent)}.gallery-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px}.concept{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:17px;overflow:hidden;text-decoration:none;transition:transform .2s,box-shadow .2s}.concept:hover{transform:translateY(-4px);box-shadow:0 12px 30px #253b2e0c}.concept-preview{height:230px;position:relative;display:grid;place-items:center;overflow:hidden;padding:25px}.mini-window{width:88%;height:200px;margin-top:35px;border-radius:10px 10px 0 0;border:1px solid #ffffff55;background:#fff;box-shadow:0 14px 35px #0001;overflow:hidden;padding:16px}.mini-top{font-size:12px;font-weight:750;display:flex;justify-content:space-between;align-items:center;padding-bottom:10px;border-bottom:1px solid #ddd8}.mini-body{display:grid;grid-template-columns:1.4fr 1fr;gap:12px;margin-top:12px}.mini-block{border-radius:7px;padding:16px;min-height:92px}.mini-block strong{display:block;font-size:19px;line-height:1.3;letter-spacing:-.5px}.mini-lines{padding:12px 0}.mini-lines i{display:block;height:5px;background:currentColor;opacity:.13;margin-bottom:9px;border-radius:8px}.mini-lines i:nth-child(2){width:80%}.concept-text{padding:26px;display:flex;flex:1;flex-direction:column;gap:10px}.concept-text h2{font-size:27px}.concept-text .number{font-size:11px;letter-spacing:1.3px;color:var(--muted);font-weight:650}.concept-text p{font-size:13px;line-height:1.7;flex:1}.concept-cta{font-size:12px;font-weight:700;margin-top:8px;display:flex;justify-content:space-between;align-items:center}.concept:last-child{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr}.concept:last-child .concept-preview{height:100%;min-height:250px}.gallery-note{margin-top:30px;display:grid;grid-template-columns:repeat(3,1fr);gap:25px;padding:28px;border:1px solid var(--line);border-radius:17px}.gallery-note h3{font-size:14px;margin:12px 0 7px}.gallery-note p{font-size:12px}.gallery-note .icon{color:var(--accent)}
@media(max-width:650px){.gallery-grid{grid-template-columns:1fr}.concept:last-child{display:flex;grid-column:auto}.concept:last-child .concept-preview{height:230px;min-height:230px}.gallery-note{grid-template-columns:1fr}.gallery-hero{padding-top:4px}.gallery-hero h1{font-size:44px}.concept-preview{height:215px}.concept-text{padding:23px}}
'''

